// Generated by tools/cpc-en/build-goods.js — edit tools/cpc-en/goods/*.json instead
window.CPC_GOODS_EN = {"g10":{"title":"Goods 10 - Road Haulage Operator Licensing and Market Access","questions":[{"q":"In Ireland, who needs a Road Haulage Operator's Licence?","options":["Anyone carrying goods for reward in a vehicle over 3.5 t","Anyone driving any goods vehicle over 7.5 tonnes","Only hauliers who carry goods to other countries","Every company that owns a van or a lorry"],"correct":0,"exp":"A Road Haulage Operator's Licence is needed to carry goods for hire or reward (someone else's goods, for payment) in a vehicle or combination with a maximum authorised weight over 3.5 tonnes.\n📍 RSA / CVRT, Operator Licensing"},
{"q":"A builders' merchant delivers goods it has sold to its customers, in its own 18-tonne lorries driven by its employees. Does it need a road haulage licence?","options":["Yes, always over 3.5 tonnes","No: this is own-account transport","Only if it crosses a border","Only if it charges for delivery separately"],"correct":1,"exp":"Own-account work (your own goods, in your own vehicles, driven by you or your employees, including delivering goods a customer has bought from you) does not need a road haulage licence.\n📍 RSA, Road transport operator licence"},
{"q":"What does 'hire or reward' mean for goods transport?","options":["Carrying your own goods for free","Being paid to carry someone else's goods","Renting a lorry to a friend","Carrying goods between your own depots"],"correct":1,"exp":"Hire or reward means carrying someone else's goods for payment. That is what triggers the need for a road haulage operator's licence.\n📍 RSA / CVRT, Operator Licensing"},
{"q":"Which four requirements must a road haulage operator meet under Regulation (EC) 1071/2009?","options":["Good repute, finance, competence and establishment","A Euro 6 fleet, a depot, a bank loan and a CPC","IRHA membership, insurance, a website and VAT","Ten years' experience, a yard and two vehicles"],"correct":0,"exp":"The four EU requirements are good repute, appropriate financial standing, professional competence (a transport manager with the CPC) and an effective and stable establishment in the State. They must be met for as long as the licence is held.\n📍 Regulation (EC) 1071/2009, Article 3"},
{"q":"What financial standing must a haulier show for heavy goods vehicles?","options":["€5,000 for the first vehicle and €3,000 for each additional one","€9,000 for the first vehicle and €5,000 for each additional one","€12,000 for the first vehicle and €6,000 for each additional one","€1,800 for the first vehicle and €900 for each additional one"],"correct":1,"exp":"Vehicles over 3.5 t: available capital and reserves of at least €9,000 for the first vehicle and €5,000 for each additional vehicle. (€1,800 and €900 are the amounts for light commercial vehicles.)\n📍 Regulation (EC) 1071/2009, Article 7"},
{"q":"A haulier wants a licence for 6 heavy goods vehicles. How much financial standing must it show?","options":["€30,000","€34,000","€39,000","€54,000"],"correct":1,"exp":"€9,000 for the first vehicle + 5 × €5,000 for the others = €34,000.\n📍 Regulation (EC) 1071/2009, Article 7"},
{"q":"Since 21 May 2022, which light commercial vehicles need an operator licence?","options":["All vans used anywhere in Ireland","Vans over 2.5 t doing international paid work","Only electric vans used for deliveries","Only vans towing a trailer over 750 kg"],"correct":1,"exp":"Under Regulation (EU) 2020/1055, operators using light commercial vehicles over 2.5 t (up to 3.5 t) for international hire or reward transport need a licence from 21 May 2022.\n📍 Department of Transport, LCV international transport operations"},
{"q":"What financial standing is required for light commercial vehicles (2.5 to 3.5 tonnes) in international transport?","options":["€900 for the first vehicle and €450 for each additional one","€1,800 for the first vehicle and €900 for each additional one","€9,000 for the first vehicle and €5,000 for each additional one","No financial standing is needed for vans"],"correct":1,"exp":"For light commercial vehicles: €1,800 for the first vehicle and €900 for each additional vehicle.\n📍 Department of Transport, LCV international transport operations"},
{"q":"Which body issues road haulage operator licences in Ireland?","options":["The National Transport Authority (NTA)","The Department of Transport's RTOL unit","The Revenue Commissioners (Customs)","An Garda Síochána (traffic corps)"],"correct":1,"exp":"Licences are issued by the Department of Transport's Road Transport Operator Licensing (RTOL) unit, through the rtol.ie portal. The NTA deals with bus route licences, not haulage.\n📍 Department of Transport, road haulage operator licence"},
{"q":"For how long is an Irish road haulage operator licence normally valid?","options":["1 year only","3 years only","Up to 5 years","10 years or more"],"correct":2,"exp":"Licences are issued for up to five years and must then be renewed.\n📍 Department of Transport; Road Traffic and Transport Act 2006"},
{"q":"Which certificate must a haulier hold to show it is up to date with its taxes when applying for a licence?","options":["Tax clearance certificate","P60 end-of-year statement","CRW from the CVRT test","VRT registration receipt"],"correct":0,"exp":"Applicants must hold a valid tax clearance certificate, and good repute also requires Garda vetting and a self-declaration.\n📍 Department of Transport, operator licence requirements"},
{"q":"What document allows an Irish haulier to carry goods for hire or reward between EU Member States?","options":["Community Licence","ECMT multilateral permit","TIR carnet for customs","ATA temporary-import carnet"],"correct":0,"exp":"The Community Licence gives access to international road haulage within the EU. The original is kept at the operator's premises and a certified true copy is carried in each vehicle.\n📍 Regulation (EC) 1072/2009, Article 4"},
{"q":"Where must a certified true copy of the Community Licence be kept?","options":["At the operator's bank branch","In every vehicle on international work","At the RSA's head office in Ballina","At the customs office of the port"],"correct":1,"exp":"The original stays at the operator's premises; a certified true copy must be carried in each vehicle and shown on request.\n📍 Regulation (EC) 1072/2009, Article 4"},
{"q":"What is 'cabotage' in road haulage?","options":["Haulage between two different EU countries by any haulier","Haulage inside another EU country by a foreign haulier","Haulage on a ferry, a train or any other vessel","Haulage of your own goods in your own company lorry"],"correct":1,"exp":"Cabotage is national transport of goods for hire or reward carried out on a temporary basis in a host Member State by a haulier from another Member State.\n📍 Regulation (EC) 1072/2009, Article 2"},
{"q":"After an international delivery into France, how many cabotage operations may an Irish lorry carry out there?","options":["Up to 3 within 7 days of unloading","Up to 5 within 10 days of unloading","Unlimited for 30 days after unloading","None: cabotage is banned in France"],"correct":0,"exp":"Up to 3 cabotage operations within 7 days of the last unloading of the incoming international carriage.\n📍 Regulation (EC) 1072/2009, Article 8, as amended by 2020/1055"},
{"q":"After a period of cabotage in a Member State, how long must the same vehicle wait before doing cabotage there again?","options":["24 hours after the last job","4 days (cooling-off period)","7 days after the last job","1 month after the last job"],"correct":1,"exp":"Since 21 February 2022 there is a 4-day cooling-off period: the vehicle may not carry out cabotage with the same vehicle in that Member State for 4 days after the end of its cabotage period.\n📍 Regulation (EC) 1072/2009, Article 8, as amended by 2020/1055"},
{"q":"Under the EU Mobility Package, how often must a vehicle used in international transport return to an operational centre in its home Member State?","options":["Every 2 weeks at the latest","Within 8 weeks of leaving it","Every 6 months at the latest","Never: there is no such rule"],"correct":1,"exp":"Since 21 February 2022, vehicles must return to one of the operational centres in the Member State of establishment within 8 weeks of leaving it.\n📍 Regulation (EC) 1071/2009, Article 5, as amended by 2020/1055"},
{"q":"Under the Mobility Package, the operator must organise the work so that a driver can return home or to the operational centre:","options":["Every week, at the weekend","Every 4 weeks (3 in some cases)","Every 3 months at the latest","Only at the end of the contract"],"correct":1,"exp":"Drivers must be able to return home or to the employer's operational centre within each period of 4 consecutive weeks, or 3 weeks if two consecutive reduced weekly rests were taken.\n📍 Regulation (EC) 561/2006, Article 8, as amended by 2020/1054"},
{"q":"Since 2 February 2022, drivers posted to another Member State for cabotage or cross-trade must be declared through:","options":["The EU's IMI portal","The RTOL licensing portal","Revenue's ROS system","The ECMT permit office"],"correct":0,"exp":"Posting rules apply to cabotage and cross-trade (not to bilateral trips to and from the home country). The operator files a posting declaration through the EU's IMI portal and the driver must be able to show it.\n📍 Directive (EU) 2020/1057"},
{"q":"Which document lets a haulier carry goods to or through non-EU countries that belong to the International Transport Forum, such as Turkey or Serbia?","options":["An ECMT multilateral permit","A Community Licence only","A CMR note only","An EORI number"],"correct":0,"exp":"ECMT (CEMT) multilateral permits, allocated in limited numbers by quota, cover journeys between member countries of the International Transport Forum; otherwise bilateral permits are needed.\n📍 ITF / ECMT quota system"},
{"q":"A haulier from outside the EU employs a driver who is not an EU national. Which document must the driver carry for EU journeys?","options":["A driver attestation","A TIR carnet","A green card","A tachograph calibration plaque"],"correct":0,"exp":"A driver attestation certifies that a non-EU driver is lawfully employed by the operator; it is issued by the Member State of establishment and carried with the certified copy of the Community Licence.\n📍 Regulation (EC) 1072/2009, Article 5"},
{"q":"Which of these is NOT one of the four requirements for a road haulage operator licence?","options":["Good repute","Financial standing","Professional competence","Trade association membership"],"correct":3,"exp":"The four requirements are good repute, financial standing, professional competence and establishment. Joining a trade association such as the IRHA is voluntary.\n📍 Regulation (EC) 1071/2009, Article 3"}]},"g15":{"title":"Goods 15 - Goods Vehicle Taxation and Tolls","questions":[{"q":"On what basis is annual motor tax calculated for a goods vehicle in Ireland?","options":["Its CO2 emissions","Its engine size","Its unladen weight","Its number of seats"],"correct":2,"exp":"Goods vehicles are taxed on unladen weight (the weight of the vehicle without its load). Cars are taxed on CO2 and buses on seating capacity.\n📍 Citizens Information, motor tax rates"},
{"q":"What is the annual motor tax on a goods vehicle with an unladen weight of up to 3,000 kg?","options":["€92","€333","€420","€500"],"correct":1,"exp":"Up to 3,000 kg unladen: €333 a year. The next band, 3,001 to 4,000 kg, pays €420.\n📍 Motor tax rates for goods vehicles"},
{"q":"What is the annual motor tax on a goods vehicle with an unladen weight between 4,001 kg and 12,000 kg?","options":["€333","€420","€500","€900"],"correct":2,"exp":"4,001 to 12,000 kg unladen: €500 a year. Over 12,000 kg: €900.\n📍 Citizens Information, motor tax rates"},
{"q":"What is the annual motor tax on a goods vehicle with an unladen weight over 12,000 kg?","options":["€500","€900","€1,282","€2,500"],"correct":1,"exp":"Over 12,000 kg unladen: €900 a year, the top goods band since the 2016 simplification.\n📍 Citizens Information, motor tax rates"},
{"q":"To tax a light goods vehicle (up to 3,500 kg) at the commercial rate for the first time, the owner must complete:","options":["Form RF111A (Goods Only)","Form B1 (Annual Return)","Form RF100 (first tax)","A CMR consignment note"],"correct":0,"exp":"Light goods vehicles up to 3,500 kg need the Goods Only Declaration, form RF111A, to be taxed at the goods rate.\n📍 County council motor tax guidance; Dáil answer on RF111A"},
{"q":"Where is the RF111A Goods Only Declaration signed?","options":["At a solicitor's or notary's office","At a Garda station, before a Garda","At the NCT or CVRT test centre","Online, with no witness needed"],"correct":1,"exp":"The applicant signs the RF111A at a Garda station and a Garda witnesses the signature. It includes the income tax number and the nature of the trade or business.\n📍 County council motor tax guidance"},
{"q":"When is a new RF111A normally needed?","options":["Every time the tax is renewed","First tax, new owner, or private to commercial","Only when the vehicle is sold abroad","Only after an accident or a write-off"],"correct":1,"exp":"Councils ask for it when a light goods vehicle is first taxed, when ownership changes, and when the tax is switched from the private to the commercial rate.\n📍 County council motor tax guidance"},
{"q":"A van taxed at the goods rate is used for private family trips. What is the rule?","options":["It is fine at weekends and holidays","It must then be taxed at the private rate","Only the insurance policy must change","It is allowed up to 1,000 km a year"],"correct":1,"exp":"The goods rate is only for vehicles used in the course of a trade or business. A goods vehicle used privately must be taxed at the private rate like any other private vehicle.\n📍 County council motor tax guidance"},
{"q":"What must a commercial goods vehicle over one year old have before motor tax can be paid?","options":["A valid CRW from the CVRT","A valid NCT certificate","A tachograph printout","A signed CMR note"],"correct":0,"exp":"Commercial vehicles need a current CRW (issued after passing the CVRT) before they can be taxed.\n📍 RSA, CVRT"},
{"q":"How much toll does a heavy goods vehicle pay to use the Dublin Port Tunnel?","options":["The same toll as a private car","Nothing: it is free for HGVs","€25 for every single trip","€10, at peak times only"],"correct":1,"exp":"The Dublin Port Tunnel is free for HGVs, to take them off city streets; cars pay a toll designed to discourage commuter traffic.\n📍 Dublin City Council HGV Management Strategy"},
{"q":"Under Dublin City Council's HGV Management Strategy, which lorries are banned from the city-centre cordon between 7am and 7pm without a permit?","options":["All goods vehicles over 3.5 tonnes","HGVs with five or more axles","Only vehicles carrying dangerous goods","Only foreign-registered lorries"],"correct":1,"exp":"Since 19 February 2007, HGVs with five or more axles may not enter the cordon area between 07:00 and 19:00 without a permit, seven days a week. Permits exist for deliveries inside the cordon and for vehicles that cannot use the Port Tunnel.\n📍 Dublin City Council HGV Management Strategy"},
{"q":"A five-axle HGV must make a delivery inside the Dublin city cordon at 11am. What does it need?","options":["Nothing if the driver is local","A permit from Dublin City Council","A Garda escort","A CMR note stamped by the port"],"correct":1,"exp":"Deliveries inside the cordon during 07:00-19:00 need a permit. Driving in without one can be fined.\n📍 Dublin City Council HGV Management Strategy"},
{"q":"How is the M50 toll paid by a lorry?","options":["At a toll barrier, in coins","Via eFlow: plate camera, tag or online","At the nearest Garda station","It is free for all goods vehicles"],"correct":1,"exp":"The M50 uses eFlow: there are no barriers, cameras read the number plate, and the toll is paid with a tag, an account or online by 8pm the next day.\n📍 TII eFlow"},
{"q":"Which HGVs pay the UK HGV Road User Levy when driving in Great Britain?","options":["All vehicles over 3.5 tonnes","HGVs of 12 t or more, foreign too","Only British-registered lorries","Only dangerous goods vehicles"],"correct":1,"exp":"The HGV Road User Levy applies to HGVs of 12 tonnes or more on GB roads, whether UK or foreign-registered. Foreign hauliers buy it before the journey.\n📍 UK HGV Road User Levy"},
{"q":"Germany's distance-based lorry toll (LKW-Maut) is collected by:","options":["Toll Collect (on-board unit)","Paper vignettes at the border","The Irish eFlow system","Norway's AutoPASS tags"],"correct":0,"exp":"Germany's LKW-Maut is run by Toll Collect: the vehicle pays per km with an on-board unit or by booking the route in advance. The amount depends on weight, axles and CO2 class.\n📍 Toll Collect"}]},"g16":{"title":"Goods 16 - Contracts of Carriage of Goods and the CMR","questions":[{"q":"When does the CMR Convention apply to a contract for the carriage of goods by road?","options":["Only when both countries are EU members","Paid carriage between two countries (one in CMR)","On every domestic journey of over 50 km","Only when the consignment note says so"],"correct":1,"exp":"CMR applies to every contract for the carriage of goods by road in vehicles for reward, when the place of taking over and the place of delivery are in two different countries and at least one of them is a contracting country (Article 1). A domestic Irish job is not covered.\n📍 CMR, Article 1"},
{"q":"Which of these carriages is NOT covered by the CMR Convention?","options":["A pallet of machine parts from Dublin to Lyon","Furniture removal from Cork to Madrid","Frozen fish from Galway to Brussels","Paper rolls from Limerick to Milan"],"correct":1,"exp":"CMR does not apply to carriage under international postal conventions, funeral consignments or furniture removal (Article 1.4).\n📍 CMR, Article 1"},
{"q":"A haulier carries goods from Dublin to Paris without issuing a CMR consignment note. What is the position?","options":["The contract is void","The contract stays valid under CMR","Irish law applies instead of CMR","Only the sender is liable"],"correct":1,"exp":"The consignment note confirms the contract, but if it is missing, irregular or lost, the contract is still valid and remains subject to CMR (Article 4).\n📍 CMR, Article 4"},
{"q":"How many original copies of the CMR consignment note are made out?","options":["Two","Three","Four","Five"],"correct":1,"exp":"Three originals signed by the sender and the carrier: the first for the sender, the second travels with the goods to the consignee, the third is kept by the carrier (Article 5).\n📍 CMR, Article 5"},
{"q":"Which copy of the CMR note travels with the goods?","options":["The first copy","The second copy","The third copy","None: it is sent by email"],"correct":1,"exp":"First copy: sender. Second copy: accompanies the goods. Third copy: retained by the carrier.\n📍 CMR, Article 5"},
{"q":"Which of these must the CMR consignment note contain?","options":["The driver's home address","The gross weight or quantity of the goods","The vehicle's motor tax disc number","The price paid for the vehicle"],"correct":1,"exp":"Article 6 lists the contents: date and place, sender, carrier and consignee, place and date of taking over, place of delivery, description and packing of the goods, number of packages, gross weight, charges, customs instructions and a statement that the carriage is subject to CMR.\n📍 CMR, Article 6"},
{"q":"On taking over the goods, the carrier must check:","options":["The value of the goods for insurance","Package numbers, marks and apparent condition","The sender's VAT number and address","The consignee's credit rating"],"correct":1,"exp":"The carrier checks the accuracy of the statements on the number of packages, marks and numbers, and the apparent condition of the goods and their packaging. If it cannot check, or finds problems, it enters reservations on the note (Article 8).\n📍 CMR, Article 8"},
{"q":"The driver notices torn shrink-wrap on two pallets when loading. What should be done?","options":["Nothing: damage is the consignee's problem","Enter a reservation on the consignment note","Refuse all CMR liability by phone","Repair the wrapping and say nothing"],"correct":1,"exp":"Reservations about the apparent condition of the goods or packing are entered on the consignment note. Without them the goods are presumed to have been taken over in good condition.\n📍 CMR, Articles 8 and 9"},
{"q":"Under CMR the carrier is liable for loss of or damage to the goods:","options":["Only while the vehicle is actually moving","From taking over the goods until delivery","Only if the driver was proved negligent","Only while the lorry is on a motorway"],"correct":1,"exp":"The carrier is liable for total or partial loss and for damage occurring between taking over the goods and delivery, and for delay in delivery (Article 17.1).\n📍 CMR, Article 17"},
{"q":"Which of these can relieve the carrier of liability under CMR?","options":["A defect in the carrier's own vehicle","Inherent vice of the goods","The driver's tiredness","A puncture"],"correct":1,"exp":"The carrier is relieved if the loss was caused by the claimant's wrongful act or instructions, inherent vice of the goods, or circumstances it could not avoid. Defects in the vehicle it uses never relieve it (Article 17.2 and 17.3).\n📍 CMR, Article 17"},
{"q":"What is the CMR limit of compensation for loss of goods?","options":["€10 per kilogram lost","8.33 SDR per kg gross weight","The full invoice value, always","2 SDR per package lost"],"correct":1,"exp":"Compensation is calculated on the value of the goods at the place and time of taking over, and may not exceed 8.33 units of account (Special Drawing Rights) per kilogram of gross weight short (Article 23.3).\n📍 CMR, Article 23"},
{"q":"A 500 kg pallet is lost. What is the maximum CMR compensation (ignoring carriage charges and duties)?","options":["500 SDR","2,500 SDR","4,165 SDR","8,330 SDR"],"correct":2,"exp":"500 kg × 8.33 SDR = 4,165 SDR. Carriage charges, customs duties and other charges for the carriage are refunded on top (Article 23.4).\n📍 CMR, Article 23"},
{"q":"For delay in delivery, CMR compensation may not exceed:","options":["The value of the goods","The carriage charges","8.33 SDR per kilogram","Twice the carriage charges"],"correct":1,"exp":"If the claimant proves damage caused by delay, the carrier pays compensation not exceeding the carriage charges (Article 23.5).\n📍 CMR, Article 23"},
{"q":"How can the sender get compensation above the 8.33 SDR per kg limit?","options":["By insisting on it by phone beforehand","By declaring a higher value on the note","By choosing a faster route to delivery","It is never possible under the CMR"],"correct":1,"exp":"The sender may declare a higher value of the goods (Article 24) or a special interest in delivery (Article 26) on the consignment note, against payment of an agreed surcharge.\n📍 CMR, Articles 24 and 26"},
{"q":"When can the carrier NOT rely on the CMR limits of liability?","options":["When the goods are fragile","When it acted with wilful misconduct","When the journey is over 1,000 km","When the consignee is a company"],"correct":1,"exp":"The carrier loses the benefit of the limits if the damage was caused by its wilful misconduct, or by an equivalent default, including that of its servants or agents (Article 29).\n📍 CMR, Article 29"},
{"q":"When may the claimant treat the goods as lost when no delivery time was agreed?","options":["After 14 days from taking over","After 30 days from taking over","After 60 days from taking over","After one year from taking over"],"correct":2,"exp":"Goods not delivered within 30 days after an agreed time limit, or within 60 days from taking over when no time limit was agreed, are conclusively presumed lost (Article 20).\n📍 CMR, Article 20"},
{"q":"Damage that was not apparent at delivery must be notified to the carrier in writing within:","options":["24 hours from the time of delivery","7 days (excluding Sundays/holidays)","21 days from the time of delivery","30 days from the time of delivery"],"correct":1,"exp":"Apparent loss or damage: reservations at the time of delivery. Damage not apparent: in writing within 7 days of delivery, Sundays and public holidays excepted (Article 30.1).\n📍 CMR, Article 30"},
{"q":"A consignee wants compensation for delay. Within how long must it send a written reservation?","options":["7 days from the date of delivery","14 days from the date of delivery","21 days from the goods being available","3 months from the date of delivery"],"correct":2,"exp":"No compensation for delay is payable unless a reservation is sent in writing within 21 days from the time the goods were placed at the consignee's disposal (Article 30.3).\n📍 CMR, Article 30"},
{"q":"What is the normal period of limitation for legal action under CMR?","options":["6 months","1 year","2 years","6 years"],"correct":1,"exp":"One year; three years in the case of wilful misconduct or an equivalent default (Article 32).\n📍 CMR, Article 32"},
{"q":"In the case of wilful misconduct, the CMR period of limitation is:","options":["1 year","2 years","3 years","No limit"],"correct":2,"exp":"The normal limit is one year; with wilful misconduct or an equivalent default it is three years (Article 32.1).\n📍 CMR, Article 32"},
{"q":"Until when may the sender change the place of delivery or the consignee (right of disposal)?","options":["Never, once the goods are loaded","Until copy 2 is handed to the consignee","Only before the lorry leaves Ireland","Only with the Garda's permission"],"correct":1,"exp":"The sender may stop the goods, change the place of delivery or the consignee. The right ends when the second copy of the consignment note is handed to the consignee (Article 12).\n📍 CMR, Article 12"},
{"q":"Three hauliers carry one consignment under a single CMR contract. Who is responsible for the whole journey?","options":["Only the first carrier","Only the last carrier","Each of them, for the whole operation","Only the carrier that had the goods when the loss occurred"],"correct":2,"exp":"With successive carriers under one contract, each carrier is responsible for the performance of the whole operation; they then settle between themselves (Articles 34 to 37).\n📍 CMR, Articles 34-37"},
{"q":"Can a haulier's own terms and conditions reduce its liability below the CMR limits for an international job?","options":["Yes, if printed on the invoice","No: such terms are null and void","Yes, if the customer pays late","Yes, for loads under 1 tonne"],"correct":1,"exp":"Any stipulation that directly or indirectly derogates from the Convention is null and void, although the rest of the contract remains valid (Article 41).\n📍 CMR, Article 41"},
{"q":"Which party normally signs the CMR consignment note together with the sender?","options":["The consignee","The carrier","The customs officer","The insurer"],"correct":1,"exp":"The three originals are signed by the sender and by the carrier (Article 5); the consignee signs the second copy on delivery.\n📍 CMR, Article 5"},
{"q":"What must the CMR consignment note say about dangerous goods?","options":["Nothing at all","Their recognised description","Only their price","Only their country of origin"],"correct":1,"exp":"For dangerous goods, the note must contain their generally recognised description (Article 6.1(f)); the sender must also tell the carrier the exact nature of the danger (Article 22).\n📍 CMR, Articles 6 and 22"}]},"g18":{"title":"Goods 18 - Weights and Dimensions of Goods Vehicles","questions":[{"q":"What is the maximum height of any vehicle in Ireland, including its load?","options":["4.00 metres","4.30 metres","4.65 metres","4.95 metres"],"correct":2,"exp":"All vehicles: 4.65 m, and the load is included. The only exception is a vehicle carrying baled agricultural produce (hay, silage, straw).\n📍 RSA weights and dimensions guide, maximum height"},
{"q":"What is the maximum width of a rigid truck, tractor unit or semi-trailer with a design gross vehicle weight over 3.5 tonnes?","options":["2.50 metres","2.55 metres","2.60 metres","2.75 metres"],"correct":1,"exp":"Rigid trucks, tractor units, trailers and semi-trailers over 3.5 t: 2.55 m. A vehicle of 3.5 t or less: 2.5 m. A conditioned (insulated, temperature-controlled) vehicle: 2.6 m.\n📍 RSA weights and dimensions guide, maximum width"},
{"q":"A temperature-controlled 'conditioned' vehicle has insulated side walls at least 45 mm thick. What is its maximum width?","options":["2.50 metres","2.55 metres","2.60 metres","2.90 metres"],"correct":2,"exp":"A conditioned vehicle, built to carry goods at controlled temperatures with side walls (insulation included) at least 45 mm thick, may be 2.6 m wide. Other heavy goods vehicles: 2.55 m.\n📍 RSA weights and dimensions guide, definitions and maximum width"},
{"q":"What is the maximum overall width of a vehicle together with its load (other than loose agricultural produce)?","options":["2.55 metres","2.60 metres","2.75 metres","2.90 metres"],"correct":3,"exp":"Vehicle plus load: 2.9 m (9 feet 6 inches). The load itself may not stick out more than 300 mm beyond either side of the vehicle.\n📍 RSA weights and dimensions guide, maximum load overhang"},
{"q":"How far may a load project beyond either side of a goods vehicle or trailer?","options":["Not at all","Up to 150 mm","Up to 300 mm","Up to 500 mm"],"correct":2,"exp":"Side overhang: no more than 300 mm (1 foot) on either side, and the vehicle with its load must stay within 2.9 m wide.\n📍 RSA weights and dimensions guide, maximum load overhang"},
{"q":"How far may a load project beyond the rearmost point of a vehicle or trailer?","options":["1 metre","2 metres","3 metres","4 metres"],"correct":2,"exp":"Rear projection: no more than 3 m (electricity and telephone poles are an exception). If the load sticks out more than 1 m, a warning device must be carried at the rear of the load in daytime.\n📍 RSA weights and dimensions guide, maximum load overhang"},
{"q":"A load projects 1.5 m beyond the rear of a trailer in daytime. What is required?","options":["Nothing below 2 metres","A warning device on the load","A Garda escort","A local authority permit"],"correct":1,"exp":"Above 1 m of rear overhang a warning device must be carried at the rear of the load during the day. The absolute limit is 3 m.\n📍 RSA weights and dimensions guide, maximum load overhang"},
{"q":"What is the maximum length of a rigid truck?","options":["10 metres","12 metres","13.5 metres","15 metres"],"correct":1,"exp":"Rigid truck: 12 m. A trailer is also 12 m. (13.5 m and 15 m are the limits for buses.)\n📍 RSA weights and dimensions guide, maximum length"},
{"q":"What is the maximum length of an articulated vehicle (tractor unit and semi-trailer)?","options":["15.5 metres","16.5 metres","18.75 metres","22 metres"],"correct":1,"exp":"Articulated vehicle: 16.5 m. Vehicles first registered before 1 January 1991 and not over 15.5 m are not affected. A rigid truck with a drawbar trailer may be 18.75 m.\n📍 RSA weights and dimensions guide, maximum length"},
{"q":"What is the maximum length of a rigid truck towing a drawbar trailer (road train)?","options":["16.5 metres","17.5 metres","18.75 metres","20 metres"],"correct":2,"exp":"A combination of a rigid vehicle and a drawbar trailer: 18.75 m. The maximum loading space of a truck and trailer combination is 16.40 m.\n📍 RSA weights and dimensions guide, maximum length and loading space"},
{"q":"On a semi-trailer, the 12.0 m length limit is measured from:","options":["The front bumper to the rear","The kingpin to the rear of the trailer","The first axle to the last axle","The landing legs to the rear doors"],"correct":1,"exp":"For a semi-trailer, 12.0 m is measured from the axis of the kingpin to the rear of the trailer. The swing radius (kingpin to any point on the front of the trailer) may not exceed 2.04 m.\n📍 RSA weights and dimensions guide, maximum length"},
{"q":"Every vehicle and combination must be able to turn within the area between two circles. What are their radii?","options":["10.5 m and 4.0 m","12.5 m and 5.3 m","14.0 m and 6.0 m","15.0 m and 7.2 m"],"correct":1,"exp":"Turning circle: the vehicle or combination must be driven between concentric circles of 12.50 m and 5.30 m radius without any part going outside that area.\n📍 RSA weights and dimensions guide, manoeuvrability criteria"},
{"q":"What is the maximum weight on a single non-driving axle?","options":["8 tonnes","10 tonnes","11.5 tonnes","12 tonnes"],"correct":1,"exp":"Single axle: 10 t. The sole driving axle may carry 10.5 t, or 11.5 t with air suspension or an equivalent system.\n📍 RSA weights and dimensions guide, axles and wheels"},
{"q":"What is the maximum weight on the sole driving axle of a lorry with air suspension?","options":["10 tonnes","10.5 tonnes","11.5 tonnes","13 tonnes"],"correct":2,"exp":"Sole driving axle with twin tyres: 10.5 t, or 11.5 t with air suspension or an equivalent system.\n📍 RSA weights and dimensions guide, axles and wheels"},
{"q":"What is the maximum weight on a triaxle whose outer axles are 1.3 m or more apart?","options":["18 tonnes","21 tonnes","24 tonnes","27 tonnes"],"correct":2,"exp":"Triaxle: 24 t if the spacing is 1.3 m or more, 21 t if less. A tandem with 1.3 m or more spacing: 18 t.\n📍 RSA weights and dimensions guide, triaxle and tandem axles"},
{"q":"What is the maximum laden weight of a two-axle rigid truck whose axles are 3 m or more apart?","options":["16 tonnes","18 tonnes","19.5 tonnes","20 tonnes"],"correct":1,"exp":"Two-axle rigid: 18 t with an axle spacing of 3 m or more, 16 t if less than 3 m.\n📍 RSA weights and dimensions guide, rigid vehicles"},
{"q":"What is the maximum laden weight of a three-axle rigid truck with twin tyres and air suspension on the driving axles?","options":["24 tonnes","25 tonnes","26 tonnes","28 tonnes"],"correct":2,"exp":"Three-axle rigid: 25 t, or 26 t with twin tyres and air suspension (or equivalent) on each driving axle. The tonnes-per-metre rule (5.5 t per metre of wheelbase) also applies.\n📍 RSA weights and dimensions guide, rigid vehicles"},
{"q":"What is the maximum laden weight of a four-axle rigid truck that is an 'appropriate motor vehicle'?","options":["30 tonnes","32 tonnes","34 tonnes","36 tonnes"],"correct":1,"exp":"Four-axle rigid: 30 t, or 32 t if it is an appropriate motor vehicle (twin tyres, air suspension on driving axles, ABS). The Department kept it at 32 t to protect roads and bridges.\n📍 RSA weights and dimensions guide, rigid vehicles"},
{"q":"An 'appropriate motor vehicle' (needed for the higher weight limits) must have:","options":["3+ axles, twin tyres, air suspension, ABS","A Euro 6 engine and a smart tachograph","A refrigerated body and side guards","A loader crane with outriggers"],"correct":0,"exp":"Appropriate motor vehicle: at least three axles, twin tyres, air suspension (or equivalent) on each driving axle and ABS brakes, with the required plate.\n📍 RSA weights and dimensions guide, definitions"},
{"q":"What is the maximum weight of a five-axle articulated vehicle made of a 2-axle tractor unit and a 3-axle semi-trailer?","options":["38 tonnes","40 tonnes","42 tonnes","44 tonnes"],"correct":1,"exp":"2+3 articulated: 40 t. Ireland allowed 42 t under a derogation until 30 June 2016; that has ended. A 3-axle 'appropriate' tractor with a 2-axle semi-trailer (3+2) may run at 42 t.\n📍 RSA weights and dimensions guide, two-axle tractor unit combinations"},
{"q":"A 3-axle 'appropriate' tractor unit pulls a 2-axle semi-trailer carrying a 40-foot ISO container on an intermodal journey. What is the maximum weight?","options":["40 tonnes","42 tonnes","44 tonnes","46 tonnes"],"correct":2,"exp":"3+2 appropriate combination: 42 t, rising to 44 t when carrying a 40-foot ISO container on an intermodal journey.\n📍 RSA weights and dimensions guide, three-axle tractor unit combinations"},
{"q":"What is the maximum weight of a six-axle articulated vehicle (3+3) that meets all the extra safety criteria?","options":["40 tonnes","42 tonnes","44 tonnes","46 tonnes"],"correct":3,"exp":"Since 1 April 2013 a 3-axle tractor with a 3-axle semi-trailer may run at 46 t if both are 'appropriate' and meet the extra criteria (EBS; ESC on tractors and roll stability control on trailers registered from that date). Otherwise 44 t.\n📍 RSA weights and dimensions guide, note 6"},
{"q":"To run at 46 tonnes, a tractor unit and semi-trailer already in service on 1 April 2013 need:","options":["EBS braking (ABS alone is not enough)","ABS braking on every axle only","A speed limiter set at 80 km/h","A second driver on every trip"],"correct":0,"exp":"Vehicles already in service need EBS (ABS is not sufficient). New tractor units also need Electronic Stability Control and new semi-trailers roll stability control.\n📍 RSA weights and dimensions guide, note 6"},
{"q":"Since when may six-axle rigid truck and drawbar trailer combinations run at 46 tonnes?","options":["1 April 2013","1 June 2015","1 January 2016","They may not"],"correct":1,"exp":"From 1 June 2015 six (or more) axle rigid truck and drawbar trailer combinations may run at 46 t, with EBS and, for new vehicles, ESC and roll stability control. Artics got 46 t on 1 April 2013.\n📍 RSA weights and dimensions guide, note 7"},
{"q":"A four-axle tractor unit with a semi-trailer would weigh more than 46 tonnes. What is needed?","options":["Nothing if the tyres are new","A local authority permit","Only a Garda escort","A second tachograph"],"correct":1,"exp":"A four-axle tractor unit with an appropriate semi-trailer follows the manufacturer's specification, but over 46 t it needs a local authority permit (abnormal load).\n📍 RSA weights and dimensions guide, four-axle tractor units"},
{"q":"The 'tonnes per metre' rule for most articulated combinations allows how much weight per metre of distance from the kingpin to the rearmost axle?","options":["4.5 tonnes","5.0 tonnes","5.5 tonnes","6.5 tonnes"],"correct":2,"exp":"Most articulated combinations: 5.5 t per metre (from the kingpin to the centre of the rearmost axle). For a 46 t six-axle combination it is 5.75 t per metre.\n📍 RSA weights and dimensions guide; S.I. No. 43 of 2013"}]},"g22":{"title":"Goods 22 - HGV Speed Limits, Speed Limiters and Truck Licences","questions":[{"q":"What is the speed limit for a goods vehicle over 3,500 kg on an Irish motorway?","options":["80 km/h","90 km/h","100 km/h","120 km/h"],"correct":1,"exp":"Goods vehicles with a design gross weight over 3,500 kg: 90 km/h on motorways (raised from 80 km/h in 2012) and 80 km/h on other roads, unless a lower limit applies.\n📍 S.I. No. 75 of 2012"},
{"q":"What is the speed limit for a goods vehicle over 3,500 kg on a national road (not a motorway)?","options":["60 km/h","80 km/h","90 km/h","100 km/h"],"correct":1,"exp":"On roads other than motorways the ordinary limit for HGVs is 80 km/h, unless the road has a lower limit (for example 50 km/h in towns).\n📍 Road traffic speed limits for HGVs"},
{"q":"At what speed must the speed limiter of a goods vehicle over 3,500 kg be set?","options":["80 km/h","85 km/h","90 km/h","100 km/h"],"correct":2,"exp":"Goods vehicles over 3,500 kg must have a speed limiter set so the vehicle cannot exceed 90 km/h. Buses and coaches are set at 100 km/h.\n📍 Directive 2002/85/EC"},
{"q":"Who enforces speed limits and speed limiter rules on Irish roads?","options":["The RSA alone","An Garda Síochána","Transport Infrastructure Ireland","The local council"],"correct":1,"exp":"Enforcement of the speed regulations on the road is a matter for the Garda Síochána; the RSA also checks limiters at CVRT and roadside checks.\n📍 Dáil answers on HGV speed limits"},
{"q":"A truck with a speed limiter set at 90 km/h is driving on a national road with an 80 km/h limit. What may it do?","options":["Drive at 90 km/h because that is the limiter setting","Drive at no more than 80 km/h","Drive at 100 km/h when overtaking","Ignore the limit at night"],"correct":1,"exp":"The limiter is a maximum the vehicle can physically reach; the legal limit on that road is still 80 km/h for HGVs.\n📍 HGV speed limits"},
{"q":"Which licence category covers goods vehicles between 3,500 kg and 7,500 kg?","options":["B","C1","C","D1"],"correct":1,"exp":"C1: vehicles over 3,500 kg and not over 7,500 kg. C: vehicles over 3,500 kg with no upper limit. B is up to 3,500 kg.\n📍 Directive 2006/126/EC; RSA licence categories"},
{"q":"Which licence category is needed to drive an articulated lorry (tractor unit and semi-trailer)?","options":["C","CE","C1E","BE"],"correct":1,"exp":"A category C vehicle towing a trailer over 750 kg, which includes articulated vehicles and drawbar combinations, needs CE.\n📍 Directive 2006/126/EC; RSA licence categories"},
{"q":"What is the normal minimum age for a category C (truck) licence in Ireland?","options":["18","21","23","24"],"correct":1,"exp":"21 for categories C and CE. It drops to 18 for a driver who holds the Driver CPC.\n📍 RSA; Dáil answer 14 May 2024"},
{"q":"A driver who holds the Driver CPC can get a category C licence from the age of:","options":["17","18","19","21"],"correct":1,"exp":"The minimum age of 21 for C and CE is lowered to 18 when the driver holds the Driver Certificate of Professional Competence.\n📍 Dáil answer 14 May 2024"},
{"q":"What is the minimum age for a category C1 (small truck) learner permit?","options":["17","18","21","24"],"correct":1,"exp":"C1 (3,500 to 7,500 kg): from 18. A full category B licence is needed first.\n📍 RSA, truck categories"},
{"q":"Before applying for a category C learner permit, a driver must hold:","options":["A full category B licence","A category D licence","A motorbike licence","A forklift certificate"],"correct":0,"exp":"To learn to drive a truck you must already hold a full category B (car) licence.\n📍 RSA, truck categories"},
{"q":"A haulier's goods vehicle with a design gross weight of 3,500 kg or less (a van) on the motorway follows:","options":["The HGV limit of 90 km/h","The ordinary limits for the road","A fixed 80 km/h limit everywhere","A fixed 100 km/h limit everywhere"],"correct":1,"exp":"The 90/80 km/h HGV limits apply to goods vehicles over 3,500 kg design gross weight. Vans up to 3,500 kg follow the ordinary limits for the road.\n📍 HGV speed limits"},
{"q":"How many hours of periodic training must a truck driver complete every 5 years to keep the Driver CPC?","options":["14 hours","21 hours","35 hours","70 hours"],"correct":2,"exp":"35 hours every 5 years (normally one 7-hour module a year) at an RSA-approved centre. The same 35 hours count for both C and D licences.\n📍 RSA, Driver CPC"},
{"q":"Where can a truck driver show proof of the Driver CPC at a roadside check?","options":["The Driver Qualification Card","The CMR consignment note","The motor tax disc","The tachograph plaque"],"correct":0,"exp":"Drivers carry their Driver Qualification Card (DQC) or have the Union code 95 on their driving licence.\n📍 RSA, Driver CPC"}]}};
